(()=>{const names={cut:'直接切换',fade:'叠化',fadeblack:'淡入淡出（黑场）',wipeleft:'向左擦除',slideright:'向右滑动',smoothleft:'平滑左移'};function cfg(){return data.filmTransitions??={mode:'cut',type:'fade',duration:.3,pool:['fade','fadeblack'],boundaries:{}};}const key=(a,b)=>a+'>'+b;function choose(items){const c=cfg();return items.slice(1).map((x,i)=>{const from=items[i].target.shot_id||items[i].target.id,to=x.target.shot_id||x.target.id,k=key(from,to);let type='cut';if(c.mode==='uniform')type=c.type;if(['custom','random'].includes(c.mode))type=c.boundaries[k]||'cut';return{from,to,type,duration:type==='cut'?0:Number(c.duration)};});}function randomize(){const c=cfg(),pool=c.pool?.length?c.pool:['fade'];const items=filmItems();items.slice(1).forEach((x,i)=>{c.boundaries[key(items[i].target.shot_id||items[i].target.id,x.target.shot_id||x.target.id)]=pool[Math.floor(Math.random()*pool.length)];});save();}
function draw(){const panel=document.querySelector('#panel');if(tab!==5||!panel)return;const c=cfg(),items=filmItems(),busy=filmExports.some(j=>!j.deleted&&['queued','running'].includes(j.status)),box=document.createElement('div');box.className='card';box.id='filmTransitions';box.style.marginBottom='20px';box.innerHTML='<h3>分镜转场</h3><div style="display:flex;gap:16px;flex-wrap:wrap"><label>转场方式<select id="filmTransitionMode"><option value="cut">直接切换</option><option value="uniform">统一转场</option><option value="custom">逐镜选择</option><option value="random">随机转场</option></select></label>'+(c.mode==='uniform'?'<label>转场效果<select id="filmTransitionType">'+Object.entries(names).map(([k,n])=>'<option value="'+k+'">'+n+'</option>').join('')+'</select></label>':'')+(c.mode!=='cut'?'<label>转场时长（秒）<input id="filmTransitionDuration" type="number" min="0.1" max="2" step="0.1" value="'+c.duration+'"></label>':'')+'</div><p class="subtle">默认0.3秒。转场会重叠交界画面，成片相应缩短；配乐与字幕同步调整。为避免两人对白重叠，必要时缩短转场或改为直接切换。</p>'+(c.mode==='random'?'<div>'+Object.entries(names).filter(([k])=>k!=='cut').map(([k,n])=>'<label style="display:inline-block;margin-right:15px"><input type="checkbox" data-transition-pool="'+k+'" '+(c.pool.includes(k)?'checked':'')+'> '+n+'</label>').join('')+'</div><button id="filmRandomize">重新随机</button>':'')+(['custom','random'].includes(c.mode)?'<div style="max-height:300px;overflow:auto;margin-top:16px">'+choose(items).map(t=>'<label style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:8px 0"><span>'+esc(t.from+' → '+t.to)+'</span>'+(c.mode==='uniform'?'<b>'+esc(names[t.type])+'</b>':'<select data-transition-boundary="'+esc(key(t.from,t.to))+'">'+Object.entries(names).map(([k,n])=>'<option value="'+k+'" '+(t.type===k?'selected':'')+'>'+n+'</option>').join('')+'</select>')+'</label>').join('')+'</div>':'');const anchor=panel.querySelector('.card');anchor?.before(box);const q=id=>box.querySelector('#'+id);q('filmTransitionMode').value=c.mode;q('filmTransitionMode').onchange=e=>{c.mode=e.target.value;if(c.mode==='random')randomize();save();stage();};if(q('filmTransitionType')){q('filmTransitionType').value=c.type;q('filmTransitionType').onchange=e=>{c.type=e.target.value;save();stage();};}q('filmTransitionDuration')?.addEventListener('change',e=>{const d=Number(e.target.value);c.duration=Math.max(.1,Math.min(2,Number.isFinite(d)?d:.3));e.target.value=c.duration;save();});box.querySelectorAll('[data-transition-pool]').forEach(el=>el.onchange=()=>{const pool=[...box.querySelectorAll('[data-transition-pool]:checked')].map(x=>x.dataset.transitionPool);c.pool=pool;save();});q('filmRandomize')?.addEventListener('click',()=>{randomize();stage();});box.querySelectorAll('[data-transition-boundary]').forEach(el=>el.onchange=()=>{c.boundaries[el.dataset.transitionBoundary]=el.value;save();});if(busy)box.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);}
const oldStage=stage;stage=function(){oldStage();if(tab===5)draw();};const oldFetch=frontFetch;frontFetch=async function(url,body){if(url==='/api/film-export'&&body?.items){const targets=body.items.map(i=>({target:{shot_id:i.target_id}}));body={...body,transitions:choose(targets)};}return oldFetch(url,body);};const css=document.createElement('style');css.textContent='#filmExportHistory{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;align-items:start}#filmExportHistory>.card{min-width:0;margin-top:0!important}#filmExportHistory video{max-height:280px!important}#filmExportHistory a{display:inline-block;padding:8px 12px} @media(max-width:800px){#filmExportHistory{grid-template-columns:minmax(0,1fr)}}';document.head.append(css);render();})();
